    {
      "type": "obligation",
      "statement": "OpCo, as Controller, shall evaluate the impact of the proposed processing operations on the protection of Personal Data before carrying out processing using modern technologies that would pose a high risk to the privacy and confidentiality of the Data Subject's Personal Data.",
      "inject_refs": ["S2-I1"],
      "rationale": {
        "observation": "The chatbot account-lookup tool exposed another subscriber's billing address and call records, indicating high risk.",
        "rule": "UAE PDPL Article 21 requires a data protection impact assessment before high-risk modern technology processing.",
        "inference": "The chatbot tool is modern technology posing high risk; OpCo must ensure a DPIA is completed before continuing or expanding its use."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0066",
          "quote": "Taking into account the nature, scope and purposes of data processing, the Controller shall, before carrying out the processing, evaluate the impact of the proposed processing operations on the protection of Personal Data, when using any of the modern technologies that would pose a high risk to the privacy and confidentiality of the Data Subject's Personal Data."
        }
      ],
      "deadline_hours": null
    },
    {
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "The provided UAE PDPL excerpts contain no specific obligation or deadline for OpCo to notify the data protection authority/regulator or data subjects of a personal data breach; only general security and DPIA obligations appear.",
      "inject_refs": ["S2-I1"],
      "rationale": {
        "observation": "Customer care reported a personal data breach but the UAE excerpts do not include a breach notification article.",
        "rule": "UAE PDPL Article 7 imposes general security obligations but does not specify breach notification steps or deadlines.",
        "inference": "There is a gap in the provided UAE legal framework regarding explicit personal data breach notification requirements."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0021",
          "quote": "Take appropriate technical and organizational measures to implement the necessary standards to protect and secure Personal Data in order to preserve its confidentiality and privacy, and to ensure that it is not breached, destroyed, altered or tampered with, taking into account the nature, scope and purposes of processing and the possibility of risks to the confidentiality and privacy of the Data Subject's Personal Data."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "EU-GDPR#0040",
          "quote": "(87) It should be ascertained whether all appropriate technological protection and organisational measures have been implemented to establish immediately whether a personal data breach has taken place and to inform promptly the supervisory authority and the data subject."
        }
      ]
    }
  ]
}

